// ---------------------------------------------------------------- Metal
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

// The Metal counterparts of LinearFn and AttentionFn: dispatches into an open compute
// encoder, with the pipeline that encoder function expects.
typedef void (*EncodeLinearFn)(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                               id<MTLBuffer> X, id<MTLBuffer> W, id<MTLBuffer> Y,
                               uint32_t batch, uint32_t in, uint32_t out);
typedef void (*EncodeAttentionFn)(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                                  id<MTLBuffer> q, id<MTLBuffer> Kc, id<MTLBuffer> Vc, id<MTLBuffer> len,
                                  id<MTLBuffer> out, uint32_t batch, uint32_t hQ, uint32_t hKv,
                                  uint32_t maxSeq, float scale);
// The Metal counterpart of SampleFn; returns false if a stage refused to dispatch.
typedef bool (*EncodeSampleFn)(id<MTLComputeCommandEncoder> enc, void* ctx, id<MTLBuffer> logits,
                               id<MTLBuffer> tokens, id<MTLBuffer> rngStep, uint32_t batch, uint32_t vocab);

// Compiled by the driver, each from its own lab's kernel.metal with the constants that
// lab's driver uses.
struct LlamaPipelines {
    id<MTLComputePipelineState> embed;        // lab 22.2's embed_rows
    id<MTLComputePipelineState> rmsNorm;      // lab X3.1's rms_norm_rows
    id<MTLComputePipelineState> linear;       // the pipeline encodeLinear expects
    id<MTLComputePipelineState> rope;         // lab X3.1's rope_rows
    id<MTLComputePipelineState> kvAppend;     // lab 20.4's kv_append
    id<MTLComputePipelineState> attention;    // the pipeline encodeAttention expects
    id<MTLComputePipelineState> addResidual;  // lab 2.3's add_residual
    id<MTLComputePipelineState> swiglu;       // lab X3.1's swiglu
    id<MTLComputePipelineState> argmax;       // lab 10.3's argmax_rows
    id<MTLComputePipelineState> advance;      // advance_positions, from your kernel.metal
};

struct LlamaLayer {
    id<MTLBuffer> rmsAtt, wq, wk, wv, wo, rmsFfn, w1, w2, w3;   // shapes as on CUDA
};

struct LlamaModel {
    LlamaConfig cfg;
    id<MTLBuffer> E;               // [vocab x d], also the LM head's weight
    const LlamaLayer* layer;       // layer[l] for l < cfg.n_layers
    id<MTLBuffer> rmsFinal;        // [d]
    EncodeLinearFn encodeLinear;   // which GEMM the step uses: the driver sets it
    EncodeAttentionFn encodeAttention;
    uint32_t ropeMode;
    float eps;
    LlamaPipelines pipelines;
};

struct LlamaState {
    uint32_t batch;
    id<MTLBuffer> tokens, pos, len;   // [batch] int32 each
    id<MTLBuffer> prompt;             // [promptLen x batch] int32
    uint32_t promptLen;
    id<MTLBuffer> out;                // [seqLen x batch] int32
    id<MTLBuffer> rngStep;            // [batch] uint64
    id<MTLBuffer> x, xb, xb2, q, k, v, att, hb, hb2, logits;
    NSArray<id<MTLBuffer>>* Kc;       // Kc[l]: [batch x seqLen x h_kv x 128]
    NSArray<id<MTLBuffer>>* Vc;
    id<MTLBuffer> cosT, sinT;         // [seqLen x 64]
    EncodeSampleFn encodeSample;      // null unless the driver sets it (lab X1.3 present, temperature > 0)
    void* sampleCtx;
};

// ---- yours, in <variant>/launch.mm (advance_positions is in <variant>/kernel.metal) ----
// Encodes one greedy decode step, then the advance, into `enc`, which the caller opened (a
// serial compute encoder) and will end and commit: the whole step is one command buffer.
// Returns false if a piece refused to dispatch.
bool encodeLlamaStep(id<MTLComputeCommandEncoder> enc, const LlamaModel& m, LlamaState& s);
void encodeAdvancePositions(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                            const LlamaState& s);

// ---- provided: reference solutions of earlier labs ----
// Lab 22.2 (M8).
void encodeEmbed(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                 id<MTLBuffer> E, id<MTLBuffer> tokens, id<MTLBuffer> H, uint32_t batch, uint32_t d);
// Lab X3.1. RMSNorm returns false, without dispatching, if the pipeline cannot run its threadgroup.
bool encodeRmsNorm(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                   id<MTLBuffer> X, id<MTLBuffer> w, id<MTLBuffer> Y, uint32_t rows, uint32_t d, float eps);
void encodeRope(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                id<MTLBuffer> X, id<MTLBuffer> pos, id<MTLBuffer> cosT, id<MTLBuffer> sinT,
                uint32_t rows, uint32_t heads, uint32_t headDim, uint32_t mode);
void encodeSwiGLU(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                  id<MTLBuffer> G, id<MTLBuffer> U, id<MTLBuffer> Y, uint32_t n);
// Lab 20.4 (M7).
void encodeKvAppend(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                    id<MTLBuffer> kNew, id<MTLBuffer> vNew, id<MTLBuffer> Kc, id<MTLBuffer> Vc,
                    id<MTLBuffer> pos, uint32_t batch, uint32_t maxSeq, uint32_t hKv);
// Lab 2.3 (M0).
void encodeAddResidual(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                       id<MTLBuffer> X, id<MTLBuffer> R, uint32_t n);
// Lab 10.3 (M4). Returns false, without dispatching, if the pipeline cannot run 256 threads
// per threadgroup in whole SIMD-groups.
bool encodeArgmaxRows(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                      id<MTLBuffer> x, id<MTLBuffer> idx, uint32_t rows, uint32_t cols);
